        'start' => [
            'Talk to your doctor or therapist about whether a device may help.',
            'Book an assessment with a prosthetist or orthotist.',
            'Attend fittings and trials and ask questions about care and use.',
            'Arrange regular reviews and know who to call if something does not feel right.',
